export function translate(text,language='zh',values={}){
  let copy=language==='en'?(EN[text]??text):text;
  if(language==='en'&&values.count===1){if(text==='已选择 {count} 个音符。')copy='{count} note selected.';if(text==='同时弹响 · {count} 个音')copy='Playing together · {count} note';}
  return copy.replace(/\{(\w+)\}/g,(match,key)=>values[key]===undefined?match:String(values[key]));
}
export function detectLanguage(nav={}){
  for(const value of nav.languages||[nav.language||'']){if(/^en(?:-|$)/i.test(value))return 'en';if(/^zh(?:-|$)/i.test(value))return 'zh';}
  return 'zh';
}
export function mountI18n({document:doc,navigator:nav={},storage,language}){
  const key='fret-note-language',listeners=new Set(),text=[],attributes=[];
  let preference=['zh','en'].includes(language)?language:'auto';
  if(preference==='auto')try{const saved=storage?.getItem(key);if(['zh','en','auto'].includes(saved))preference=saved;}catch{}
  let current=preference==='auto'?detectLanguage(nav):preference;
  function collect(node){
    if(node.nodeType===3&&/\p{Script=Han}/u.test(node.nodeValue))text.push([node,node.nodeValue]);
    if(node.nodeType===1){
      if(node.matches('script,style,[data-native-language]'))return;
      for(const attr of ['title','aria-label','placeholder','content'])if(node.hasAttribute(attr)&&/\p{Script=Han}/u.test(node.getAttribute(attr)))attributes.push([node,attr,node.getAttribute(attr)]);
    }
    for(const child of node.childNodes||[])collect(child);
  }
  collect(doc.documentElement);
  function render(){
    doc.documentElement.lang=current==='en'?'en':'zh-CN';
    for(const [node,original] of text){const trimmed=original.trim();node.nodeValue=original.replace(trimmed,translate(trimmed,current));}
    for(const [node,attr,original] of attributes)node.setAttribute(attr,translate(original,current));
    const selector=doc.getElementById('language-select');if(selector)selector.value=preference;
    listeners.forEach(listener=>listener(current));
  }
  function setLanguage(value){if(!['zh','en','auto'].includes(value))return;preference=value;current=value==='auto'?detectLanguage(nav):value;try{storage?.setItem(key,value);}catch{}render();}
  doc.getElementById('language-select')?.addEventListener('change',event=>setLanguage(event.target.value));
  render();
  return {get language(){return current;},get preference(){return preference;},t:(text,values)=>translate(text,current,values),setLanguage,subscribe(listener){listeners.add(listener);return ()=>listeners.delete(listener);}};
}
